pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(0xA11CE);

    function setUp() public {
        c = new C();
        vm.prank(deployer);
        c.initialize();
    }

    function testFuzz_property(address caller, bool renounce) public {
        vm.assume(caller != address(0));
        vm.assume(caller != deployer);

        if (renounce) {
            vm.prank(deployer);
            c.renounceOwnership();
        }

        // Rule: for ANY caller, c.owner() returns the same value (the stored owner,
        // possibly address(0) after renounce). Owner lookup is caller-independent.
        vm.prank(caller);
        address observed = c.owner();
        assertTrue(
            observed == (renounce ? address(0) : deployer),
            "owner() must be caller-independent"
        );
    }
}

