pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address actor, address newImpl) public {
        // owner is the deployer (this contract); allow any caller but prank the actor
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: an update either reverts, or (when authorized) succeeds and
        // the stored implementation is a real (non-zero) address matching the input.
        // The mutant accepts address(0), succeeding with a stored zero address.
        assertTrue(!(ok && newImpl == address(0)) && (!ok || c.roundImplementation() == newImpl));
    }
}

