contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        // Wide domain: the fuzzer may supply ANY address, including address(0).
        // Only the owner (the deployer, which is this test contract) may call.
        vm.prank(address(this));
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a successful update must store a NON-ZERO round implementation.
        // Reference: reverts on address(0) (ok == false). Mutant: succeeds with address(0),
        // leaving c.roundImplementation() == address(0) after a successful call.
        assertTrue(!(ok && c.roundImplementation() == address(0)));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // initialize so this contract becomes the owner; without this both P and M revert identically
        c.initialize();
    }

    function testFuzz_property(uint256 seed) public {
        // Wide domain: the fuzzer's seed decides the implementation address.
        // Mapping mod 2 keeps address(0) reachable with high probability
        // (the deciding value is chosen by the fuzzer, not hard-coded).
        address impl = address(uint160(seed % 2));

        vm.prank(address(this));
        bool ok;
        try c.updateRoundImplementation(payable(impl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful update must leave a non-zero round implementation.
        // Reference: reverts on address(0) (ok=false) or stores impl != 0 -> holds.
        // Mutant: succeeds and stores address(0) when the fuzzer picks seed % 2 == 0 -> breaks.
        assertTrue(!(ok && c.roundImplementation() == address(0)));
    }
}

