pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this);
        c.initialize();
    }

    function testFuzz_property(address newRoundImplementation) public {
        vm.assume(newRoundImplementation != address(0));

        c.updateRoundImplementation(payable(newRoundImplementation));

        assertTrue(c.roundImplementation() == newRoundImplementation);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address payable newImpl) external {
        require(newImpl != address(0), "impl must be nonzero");

        bytes memory data = abi.encodeWithSelector(
            c.updateRoundImplementation.selector,
            newImpl
        );
        bool ok;
        (ok, ) = address(c).call(data);

        assert(
            !ok || (c.roundImplementation() == newImpl && c.owner() == msg.sender)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address payable newImpl) public payable {
        require(true);
        bool reverted;
        try c.updateRoundImplementation(newImpl) { reverted = false; } catch { reverted = true; }
        assert(newImpl == address(0) || reverted);
    }
    receive() external payable {}
}
